package com.example.spring_blog.purchase;import com.example.spring_blog.board.Board;import com.example.spring_blog.user.User;import jakarta.persistence.*;import lombok.AllArgsConstructor;import lombok.Builder;import lombok.Getter;import lombok.NoArgsConstructor;import org.hibernate.annotations.CreationTimestamp;import java.sql.Timestamp;@Getter@NoArgsConstructor@Entity@Builder@AllArgsConstructor@Table(name = "purchase_tb",        uniqueConstraints = {@UniqueConstraint(name = "uk_user_board", columnNames = {"user_id", "board_id"})})public class Purchase {    @Id    @GeneratedValue(strategy = GenerationType.IDENTITY)    private Long id;    @ManyToOne(fetch = FetchType.LAZY)    @JoinColumn(name = "user_id", nullable = false)    private User user;    @ManyToOne(fetch = FetchType.LAZY)    @JoinColumn(name = "board_id", nullable = false)    private Board board;    private int price;    @CreationTimestamp    private Timestamp timestamp;    public Purchase(User user, Board board, int price) {        this.user = user;        this.board = board;        this.price = price;    }}